var n=`1397-damper-bread`;var a=`world-1397`;var r=`AU`;var t=`oceania`;var o=8;var s=64;var d={en:`Damper Bread`,ua:`Хліб дампер`};var g={en:`Damper Bread is a dish from Australia featuring all-purpose flour, baking powder, whole cow milk. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Хліб дампер, страва кухні країни Австралія з такими основними складниками: пшеничне борошно універсальне, розпушувач тіста, цільне коров'яче молоко. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 16 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 16 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:16,i:[[`all-purpose-flour`,490,`g`],[`baking-powder`,20,`g`],[`table-salt`,8,`g`],[`whole-cow-milk`,280,`ml`],[`unsalted-butter`,55,`g`]]},{en:`Divide and shape the prepared mixture or dough into even portions and arrange on a lined baking sheet or appropriate molds, leaving enough room for expansion.`,ua:`Розділіть і сформуйте підготовлене тісто чи масу на однакові порції, викладіть на деко з пергаментом або у форми, залишивши місце для збільшення об’єму.`,t:[`pre-shaping-dough`,`final-proofing`],m:10,i:[]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 35 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 35 хвилин до готовності.`,t:[`baking`],m:35,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`golden-syrup`,65,`g`]]}];var h={slug:n,id:a,country:`AU`,region:t,servings:8,minutes:64,title:d,text:g,steps:u};export{r as country,h as default,a as id,s as minutes,t as region,o as servings,n as slug,u as steps,g as text,d as title};